(function(){
  'use strict';
  var canvas=document.getElementById('world'),seconds=0,person='yukata',mode='walk',focus='',paused=matchMedia('(prefers-reduced-motion: reduce)').matches,slow=false,previousTiming=false,loaded=false,failed=false,last=0,dirty=true,drawPopulation;
  function update(){document.getElementById('pause').textContent=paused?'Play':'Pause';document.getElementById('slow').setAttribute('aria-pressed',String(slow));document.getElementById('timing').setAttribute('aria-pressed',String(previousTiming));document.querySelectorAll('[data-person]').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.person===person));});canvas.setAttribute('aria-label',CastWorld.profiles[person].name+' in the painted neighborhood');}
  function draw(){if(!loaded)return;var pop=CastWorld.scene(seconds,person,mode),view=focus;if(previousTiming)pop.forEach(function(s){s.gaitTuning=undefined;});
    if(mode==='turns'){var g=pop[0].ground;view={x:Math.max(0,Math.min(960,g.x-320)),y:Math.max(0,Math.min(540,g.y-270)),w:640,h:360};}
    drawPopulation(pop,view);document.getElementById('status').textContent=CastWorld.profiles[person].name+' · '+(mode==='walk'?'Five neighbors, same walking controls':mode==='turns'?'Around the alley and back':'Shop visits on the familiar street')+(paused?' · Paused':'')+(slow?' · Half speed':'')+(previousTiming?' · Previous step timing':'');dirty=false;
  }
  function action(name){mode=name==='walk'||name==='turns'?name:'street';focus=['ramen','counter','meal','broth'].indexOf(name)>=0?'ramen':name==='flowers'?'flowers':'';
    seconds=name==='ramen'?VisitWorld.entranceTime:name==='counter'?VisitWorld.counterTime:name==='meal'?VisitWorld.windowTime+2:name==='broth'?VisitWorld.windowTime+47:name==='flowers'?VisitWorld.flowerTime:0;
    paused=matchMedia('(prefers-reduced-motion: reduce)').matches;last=0;dirty=true;update();
  }
  document.querySelectorAll('[data-person]').forEach(function(b){b.onclick=function(){person=b.dataset.person;dirty=true;update();};});document.querySelectorAll('[data-action]').forEach(function(b){b.onclick=function(){action(b.dataset.action);};});
  document.getElementById('pause').onclick=function(){paused=!paused;dirty=true;update();};document.getElementById('slow').onclick=function(){slow=!slow;dirty=true;update();};document.getElementById('timing').onclick=function(){previousTiming=!previousTiming;dirty=true;update();};document.getElementById('restart').onclick=function(){seconds=0;last=0;dirty=true;};document.getElementById('fullscreen').onclick=function(){if(canvas.requestFullscreen)canvas.requestFullscreen().catch(function(){document.getElementById('status').textContent='Full screen is unavailable in this browser.';});};document.addEventListener('visibilitychange',function(){last=0;});
  function tick(now){var dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(!document.hidden){if(!paused)seconds+=dt*(slow?.5:1)*CastWorld.profiles[person].pace;if(!paused||dirty)draw();}requestAnimationFrame(tick);}
  window.CastStudy={state:function(){return {loaded:loaded,failed:failed,seconds:seconds,person:person,mode:mode,focus:focus,paused:paused,slow:slow,previousTiming:previousTiming};},inspect:function(t,next,id,view){seconds=t;if(next)mode=next;if(id)person=id;if(view!==undefined)focus=view;paused=true;update();draw();}};
  var files={tall:'../assets/cast/tall.png',blouse:'../assets/cast/blouse.png',yukata:'../assets/cast/yukata.png',child:'../assets/cast/child.png',frontMealBody:'../assets/directions/front-meal.png',rearMealBody:'../assets/directions/rear-meal.png',contactBody:'../assets/directions/rear45-contact.png',entrance:'../assets/rig/entrance-layers.png',background:'../assets/street.png',sideUpper:'../assets/skin/resident-arms.png',sideLegs:'../assets/skin/resident-layered.png',props:'../assets/rig/resident.png',front:'../assets/directions/front.png',rear:'../assets/directions/rear.png',front45:'../assets/directions/front45.png',rear45:'../assets/directions/rear45.png',legs:'../assets/directions/legs.png',interior:'../assets/rig/interior.png'};
  Promise.all(Object.entries(files).map(function(entry){return new Promise(function(resolve,reject){var img=new Image();img.onload=function(){resolve([entry[0],img]);};img.onerror=reject;img.src=entry[1];});})).then(function(entries){var images=Object.fromEntries(entries);drawPopulation=VisitRenderer.renderer(canvas,images,{actorRenderer:function(ctx){return CastActor.renderer(ctx,images,CastFrames);},seats:CastActor.seats});loaded=true;document.getElementById('loading').hidden=true;draw();}).catch(function(error){failed=true;document.getElementById('loading').textContent='The character artwork could not load. Please reload to try again.';console.error(error);});update();requestAnimationFrame(tick);
})();
